def compute(vars):
    net_income = vars["v1"]
    capital_and_surplus = vars["v2"]

    if capital_and_surplus == 0:
        return None

    ratio = net_income / capital_and_surplus

    return {
        "value": ratio,
        "trace": {
            "statutory_net_income": net_income,
            "statutory_capital_and_surplus": capital_and_surplus,
            "net_income_to_capital_ratio": ratio,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "ratio"
            }
        }
    }
